import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const KINDS = [
  { kind: "w9", file: "w9.txt" },
  { kind: "insurance_certificate", file: "insurance_certificate.txt" },
  { kind: "contract", file: "contract.txt" },
] as const;

test(
  "rejecting an extraction requires a note and returns the vendor to the member",
  { tag: "@REV-06" },
  async ({ apiAs }) => {
    // Arrange: a member creates a vendor, uploads all three documents, and submits it
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const createRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("REV06 Vendor"),
        category: "services",
        contact_email: "ops@rev06-vendor.com",
      },
    });
    expect(createRes.status(), await createRes.text()).toBe(201);
    const vendor = await createRes.json();

    const docIds: Record<string, string> = {};
    for (const { kind, file } of KINDS) {
      const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: file,
            mimeType: "text/plain",
            buffer: fs.readFileSync(sample(file)),
          },
        },
      });
      expect(uploadRes.status(), await uploadRes.text()).toBe(201);
      docIds[kind] = (await uploadRes.json()).id;
    }

    for (const { kind } of KINDS) {
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${docIds[kind]}`);
            return (await res.json()).status;
          },
          { message: `${kind} document should be extracted`, timeout: 30_000 },
        )
        .toBe("extracted");
    }

    const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitRes.status(), await submitRes.text()).toBe(200);
    expect((await submitRes.json()).status).toBe("in_review");

    const extractions: Record<string, any> = {};
    for (const { kind } of KINDS) {
      const res = await reviewer.get(`/api/documents/${docIds[kind]}/extraction`);
      expect(res.status(), await res.text()).toBe(200);
      extractions[kind] = await res.json();
      expect(extractions[kind].status).toBe("pending_review");
    }
    const w9 = extractions["w9"];

    // Act: reject without a note
    const noNoteRes = await reviewer.post(`/api/extractions/${w9.id}/decision`, {
      data: { decision: "reject" },
    });

    // Assert
    expect(noNoteRes.status(), await noNoteRes.text()).toBe(422);

    // Act: reject with a note
    const rejectRes = await reviewer.post(`/api/extractions/${w9.id}/decision`, {
      data: { decision: "reject", note: "Tax ID does not match" },
    });
    expect(rejectRes.status(), await rejectRes.text()).toBe(200);
    const rejected = await rejectRes.json();
    expect(rejected.status).toBe("rejected");
    expect(rejected.review_note).toBe("Tax ID does not match");

    // Assert: vendor status is rejected
    const vendorRes = await reviewer.get(`/api/vendors/${vendor.id}`);
    expect(vendorRes.status(), await vendorRes.text()).toBe(200);
    expect((await vendorRes.json()).status).toBe("rejected");

    // Assert: audit event recorded
    const auditRes = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditRes.status(), await auditRes.text()).toBe(200);
    const audit = await auditRes.json();
    const events = audit.items.filter((e: any) => e.action === "extraction.rejected");
    expect(events, JSON.stringify(audit.items)).toHaveLength(1);
    expect(events[0].details.extraction_id).toBe(w9.id);
  },
);
